def details(row: tuple[str, str, str, list[tuple[str, str, str, str]], list[str]]) -> dict[str, Any]:
    _, p1, p2, points, formulas = row
    return {"lessonText": [p1, p2], "readableLesson": [p1, p2], "formulas": formulas,
            "keyPoints": [{"topic": a, "explanation": b, "example": c, "commonTrap": d} for a,b,c,d in points]}

def rewrite(path: Path, batch_size: int) -> dict[str, Any]:
    data = load_curriculum_js(path)
    books = [b for b in data["science"] if b.get("stage") == "junior_high"]
    units = [u for b in books for u in b.get("units", [])]
    titles = [u["name"] for u in units]
    if set(titles) != set(LESSONS):
        raise SystemExit(f"標題白名單不一致 missing={sorted(set(titles)-set(LESSONS))} extra={sorted(set(LESSONS)-set(titles))}")
    completed = 0; failed: list[dict[str, Any]] = []
    STATE.parent.mkdir(parents=True, exist_ok=True)
    for offset in range(0, len(units), max(1, batch_size)):
        batch = units[offset:offset+max(1, batch_size)]
        for unit in batch:
            row = LESSONS[unit["name"]]; unit["lessonDetails"] = details(row)
            issues = semantic_issues(row[0], unit["name"], unit["lessonDetails"])
            if issues: failed.append({"title": unit["name"], "issues": issues})
            else: completed += 1
        write_curriculum_js(path, data)
        STATE.write_text(json.dumps({"subject":"science", "stage":"junior_high", "completed":completed,
            "failed":failed, "last_offset":offset+len(batch), "batch_size":batch_size}, ensure_ascii=False, indent=2), encoding="utf-8")
    return {"total":len(units), "completed":completed, "failed":failed}

def main() -> int:
    ap=argparse.ArgumentParser(); ap.add_argument("--file",type=Path,default=CURRICULUM); ap.add_argument("--batch-size",type=int,default=4); ap.add_argument("--no-backup",action="store_true"); args=ap.parse_args()
    if not args.no_backup:
        backup=args.file.with_name(args.file.name+f".before_junior_high_physical_science_{datetime.now():%Y%m%d_%H%M%S}"); shutil.copy2(args.file,backup); print(f"backup={backup}")
    report=rewrite(args.file,args.batch_size); print(json.dumps(report,ensure_ascii=False,indent=2)); return 0 if not report["failed"] else 2

if __name__ == "__main__": raise SystemExit(main())
